// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const { workbenchScriptPath } = require('./workbench-scripts.js');

function queryStream() {
    const context = vm.createContext({ window: {}, workbench: {}, URLSearchParams });
    const script = workbenchScriptPath('queryStream.js');
    vm.runInContext(fs.readFileSync(script, 'utf8'), context, { filename: script });
    return context.workbench.queryStream;
}

const iri = value => ({ kind: 'iri', value });
const bnode = value => ({ kind: 'bnode', value });
const literal = value => ({ kind: 'literal', value });

test('Workbench result references retain raw blank node IDs and escape the complete resource envelope', () => {
    const api = queryStream();
    const cases = [
        ['node', '<_:node>'], ['', '<_:>'], ['_:node', '<_:_:node>'], ['a%20b+c', '<_:a%20b+c>'],
        ['space >\\"{}|^`\n', '<_:space\\u0020\\u003E\\u005C\\u0022\\u007B\\u007D\\u007C\\u005E\\u0060\\u000A>'],
        ['雪😀', '<_:雪😀>'], ['\\u0041', '<_:\\u005Cu0041>']
    ];
    for (const [id, reference] of cases) {
        const term = bnode(id);
        assert.equal(api.exploreResource(term), reference, `exact ID ${JSON.stringify(id)}`);
        const display = api.formatRdfTerm(term);
        assert.equal(display.label, reference);
        assert.equal(new URL(display.exploreHref, 'http://localhost/').searchParams.get('resource'), reference);
    }
});

test('nested triple references preserve blank nodes while literal contents stay literal', () => {
    const api = queryStream();
    const term = { kind: 'triple', subject: bnode('_:subject'), predicate: iri('urn:p'),
        object: { kind: 'triple', subject: bnode('a>b'), predicate: iri('urn:p'),
            object: literal('literal <_:id> >> \\') } };
    const expected = '<<( <_:_:subject> <urn:p> <<( <_:a\\u003Eb> <urn:p> "literal <_:id> >> \\\\" )>> )>>';
    assert.equal(api.exploreResource(term), expected);
    assert.equal(new URL(api.formatRdfTerm(term).exploreHref, 'http://localhost/').searchParams.get('resource'), expected);
});

test('RDF exports continue to serialize blank node labels rather than SPARQL references', () => {
    const api = queryStream();
    assert.equal(api.ntriplesTerm(bnode('node')), '_:node');
    assert.equal(api.nquadsTerm(bnode('node')), '_:node');
    assert.equal(api.exploreResource(iri('urn:literal:node')), '<urn:literal:node>');
    assert.equal(api.exploreResource(literal('<_:node>')), '"<_:node>"');
});

test('resource links keep literal control characters escaped and escape datatype IRIs', () => {
    const api = queryStream();
    assert.equal(api.exploreResource(literal('\b\f\u0000\u001f')),
        '"\\b\\f\\u0000\\u001F"');
    assert.equal(api.exploreResource({ kind: 'literal', value: 'value', datatype: 'urn:type>a' }),
        '"value"^^<urn:type\\u003Ea>');
});
